/* Account-backed multilingual workspace. The public brand homepage stays separate. */
(()=>{
 const nav=[['home','⌂','대시보드'],['upload','↑','디자인 업로드'],['editor','✎','편집기'],['translations','▤','번역 엑셀'],['variants','◎','언어별 디자인'],['downloads','↓','다운로드'],['automation','⟳','자동 업데이트']];
 const routes=new Set(nav.map(n=>n[0]).concat(['mine','campaigns','templates']));let selected='',search='',epoch=0,uploaded=null,book=null,bookName='',busy=false;
 const W=()=>window.HanpassWorkspace,T=()=>window.HanpassSvgTranslations,E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const docs=()=>W().works.filter(d=>d.kind!=='automation-settings'),project=()=>{const d=docs().find(d=>d.id===selected);return (d?.parentId?docs().find(x=>x.id===d.parentId):d)||docs().find(d=>!d.parentId)||docs()[0]};
 const name=d=>d.name||d.title||'이름 없는 디자인',lang=c=>T().languages[c]?.[0]||c;
 const date=t=>t?new Date(t).toLocaleString('ko-KR'):'저장 시각 없음';
 function message(text,error=false){const el=document.querySelector('#dsMessage');if(el){el.textContent=text;el.classList.toggle('ds-error',error)}}
 function go(page){if(busy)return;W().navigate(page)}
 function shell(page,content){document.body.classList.remove('hp-home','fw-editing');document.getElementById('app').innerHTML=`<div class="ds-shell"><header class="ds-header"><a href="/" class="ds-logo">hanpass<small>Creative Studio</small></a><input class="ds-search" aria-label="디자인 검색" placeholder="디자인, 프로젝트, 파일 이름을 검색하세요" value="${E(search)}"><span id="fwStatus" class="ds-sync" role="status"></span><span class="ds-account">${E(W().email||'로컬 사용자')}</span></header><aside class="ds-sidebar">${nav.map(([p,i,n])=>`<button data-ds-nav="${p}" class="${p===page?'active':''}"><span aria-hidden="true">${i}</span>${n}</button>`).join('')}<button class="ds-return" data-ds-nav="catalog">▦ 기본 배너 템플릿</button></aside><main class="ds-content">${content}<div id="dsMessage" class="ds-message" role="status"></div></main></div>`;document.querySelectorAll('[data-ds-nav]').forEach(b=>b.onclick=()=>go(b.dataset.dsNav));document.querySelector('.ds-search').oninput=e=>{search=e.target.value;document.querySelectorAll('[data-design-name]').forEach(c=>c.hidden=!c.dataset.designName.includes(search.toLowerCase()))};}
 const title=(h,p)=>`<div class="ds-title"><h1>${h}</h1><p>${p}</p></div>`;
 const selectProject=()=>`<label class="ds-field">프로젝트<select id="dsProject">${docs().filter(d=>!d.parentId).map(d=>`<option value="${E(d.id)}" ${project()?.id===d.id?'selected':''}>${E(name(d))}</option>`).join('')}</select></label>`;
 function bindProject(page){const el=document.querySelector('#dsProject');if(el)el.onchange=()=>{selected=el.value;render(page)}}
 function card(d,check=false){return `<article class="ds-card" data-design-name="${E(name(d).toLowerCase())}" ${search&&!name(d).toLowerCase().includes(search.toLowerCase())?'hidden':''}><div class="ds-preview" data-preview="${E(d.id)}"></div><div class="ds-card-body"><div class="ds-row ds-between">${check?`<label><input type="checkbox" data-export-id="${E(d.id)}" checked> ${E(lang(d.language||'KR'))}</label>`:`<span class="ds-badge">${d.language?E(lang(d.language)):(d.svgRef||d.svgDesign?'SVG 디자인':'배너 디자인')}</span>`}</div><h3>${E(name(d))}</h3><time>${E(date(d.updated))}</time><div class="ds-row" style="margin-top:12px"><button data-open="${E(d.id)}">✎ 편집하기</button><button data-translate="${E(d.parentId||d.id)}">번역 연결</button></div></div></article>`}
 async function previews(){const ticket=epoch;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.open;W().open(selected)});document.querySelectorAll('[data-translate]').forEach(b=>b.onclick=()=>{selected=b.dataset.translate;go('translations')});for(const el of document.querySelectorAll('[data-preview]')){const d=docs().find(d=>d.id===el.dataset.preview);if(!d)continue;try{const source=await W().source(d);if(ticket!==epoch)return;if(source){const image=new Image();image.alt=name(d);image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(HanpassSvg.serialize(HanpassSvg.clean(source).svg));el.append(image)}else{const c=await W().raster(d);if(ticket!==epoch)return;el.append(c)}}catch{el.textContent='미리보기를 불러오지 못했습니다.'}}}
 function dashboard(){const all=docs(),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(new Date());shell('home',`<section class="ds-hero"><div><h1>디자인을 올리고, 여러 언어로 완성하세요</h1><p>하나의 디자인으로, 더 넓은 세상의 고객을 만나세요.</p><div class="ds-row"><button class="ds-primary" data-ds-nav="upload">↑ 디자인 업로드</button><button class="ds-secondary" data-ds-nav="translations">▤ 번역 엑셀 업로드</button></div></div><div class="ds-steps">${[['디자인 업로드','텍스트가 살아 있는 SVG를 올려 주세요.'],['번역 연결','엑셀 문구를 디자인 요소와 연결하세요.'],['언어별 디자인 완성','각 언어를 확인하고 한 번에 내려받으세요.']].map(([a,b],i)=>`<div class="ds-step"><span>${i+1}</span><b>${a}</b>${b}</div>`).join('')}</div></section><section class="ds-stats"><div class="ds-stat">내 디자인<strong>${all.length}</strong></div><div class="ds-stat">언어별 결과<strong>${all.filter(d=>d.parentId&&d.language).length}</strong></div><div class="ds-stat">오늘 저장<strong>${all.filter(d=>d.updated&&new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul'}).format(new Date(d.updated))===today).length}</strong></div></section><div class="ds-row ds-between ds-section"><h2>최근 작업</h2><button data-ds-nav="catalog">기본 배너 템플릿 보기 →</button></div><section class="ds-grid">${all.length?all.map(d=>card(d)).join(''):'<div class="ds-empty">아직 저장한 디자인이 없습니다. 디자인을 업로드하거나 기본 배너 템플릿으로 시작하세요.</div>'}</section>`);previews()}
 function upload(){shell('upload',title('디자인 파일을 편집 가능한 템플릿으로','Figma와 Illustrator에서 작업한 디자인을 가져오세요.')+`<div class="ds-two"><div><div class="ds-drop" id="dsDrop" tabindex="0" role="button" aria-label="디자인 파일 선택"><span style="font-size:40px">↑</span><h2>파일을 여기에 놓아주세요</h2><button class="ds-primary" id="dsUpload">파일 선택</button><p>SVG, PNG, JPG, WebP · SVG는 텍스트·도형 편집, 이미지는 배경으로 가져옵니다.</p></div><input id="dsFile" type="file" accept=".svg,.png,.jpg,.jpeg,.webp" hidden><div class="ds-grid ds-section"><div class="ds-panel"><h2>Figma</h2><p>SVG로 내보내기 · Outline text 해제</p></div><div class="ds-panel"><h2>Illustrator</h2><p>SVG로 내보내기 · 텍스트 유지</p></div></div><div class="ds-warn">AI·PDF는 SVG로 내보낸 후 업로드하세요. 이미지 안의 글자와 윤곽선 문자는 개별 번역되지 않습니다.</div></div><section class="ds-panel"><h2>업로드 미리보기</h2><div id="dsUploadPreview" class="ds-preview ds-file-preview">${uploaded?'':'디자인을 선택하면 분석 결과가 표시됩니다.'}</div><div id="dsUploadReport"></div><div class="ds-row ds-section"><button id="dsOpenUpload" class="ds-primary" ${uploaded?'':'disabled'}>편집기로 열기</button><button id="dsLinkUpload" ${uploaded?'':'disabled'}>번역 엑셀 연결</button></div></section></div>`);const input=document.getElementById('dsFile'),drop=document.getElementById('dsDrop');document.getElementById('dsUpload').onclick=e=>{e.stopPropagation();input.click()};drop.onclick=()=>input.click();drop.onkeydown=e=>{if(e.key==='Enter')input.click()};input.onchange=()=>importFile(input.files[0]);drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');importFile(e.dataTransfer.files[0])};document.getElementById('dsOpenUpload').onclick=()=>W().open(uploaded.id);document.getElementById('dsLinkUpload').onclick=()=>{selected=uploaded.id;go('translations')};if(uploaded)showUpload()}
 async function showUpload(){const ticket=epoch,d=uploaded,source=await W().source(d);if(ticket!==epoch)return;const parsed=HanpassSvg.clean(source),svg=parsed.svg;document.getElementById('dsUploadPreview').replaceChildren(svg);document.getElementById('dsUploadReport').innerHTML=`<h3>${E(name(d))}</h3><p>${parsed.width} × ${parsed.height}px · 텍스트 ${svg.querySelectorAll('text').length}개 · 이미지 ${svg.querySelectorAll('image').length}개 · 도형 ${svg.querySelectorAll('rect,path,circle,ellipse,polygon,line').length}개</p><p>저장됨 · ${E(date(d.updated))}</p>`}
 async function importFile(file){if(!file||busy)return;busy=true;message('파일을 분석하고 저장하고 있습니다…');try{let source;if(/\.svg$/i.test(file.name)){source=await file.text()}else{if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('SVG, PNG, JPG, WebP 파일을 선택하세요.');const bitmap=await createImageBitmap(file),w=bitmap.width,h=bitmap.height;bitmap.close();const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});source=`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"><image width="${w}" height="${h}" href="${data}"/></svg>`}const p=HanpassSvg.clean(source),ref=await HanpassDesignStorage.save(HanpassSvg.serialize(p.svg));uploaded=W().save({id:crypto.randomUUID(),format:1,theme:0,title:file.name.replace(/\.[^.]+$/,''),name:file.name.replace(/\.[^.]+$/,''),desc:'',image:'',svgRef:ref,originalSize:[p.width,p.height]});selected=uploaded.id;busy=false;upload();message('디자인이 저장되었습니다. 편집하거나 번역 엑셀을 연결하세요.')}catch(e){message(e.message,true)}finally{busy=false}}
 async function translations(){const ticket=epoch,d=project();shell('translations',title('번역 엑셀 하나로, 여러 언어의 디자인을','이미 번역된 문구를 업로드하면 디자인 텍스트와 연결합니다.')+(!d?'<div class="ds-empty">먼저 디자인을 업로드해 주세요.<p><button data-ds-nav="upload">디자인 업로드</button></p></div>':`<div class="ds-two"><section class="ds-panel">${selectProject()}<div class="ds-row"><button id="dsExcel" class="ds-primary">번역 Excel 업로드</button><button id="dsExample">엑셀 양식 다운로드</button></div><input id="dsExcelFile" type="file" accept=".xlsx,.csv" hidden><label class="ds-field" id="dsSheetWrap" hidden>시트<select id="dsSheet"></select></label><div id="dsTranslationBody"></div></section><aside class="ds-panel"><h2>연결 결과</h2><div id="dsConnection"></div><div class="ds-checks"><label><input id="dsFit" type="checkbox" checked> 글자 크기 자동 맞춤</label></div><p>줄바꿈은 엑셀 셀의 줄바꿈을 유지합니다. 생성 후 각 언어의 글꼴과 넘침을 확인하세요.</p><button id="dsGenerate" class="ds-primary" disabled>언어별 디자인 생성</button></aside></div>`));if(!d)return;bindProject('translations');document.getElementById('dsExcel').onclick=()=>document.getElementById('dsExcelFile').click();document.getElementById('dsExample').onclick=()=>{const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([['key','ko','en','ja','mn'],['title','제목','Title','タイトル','Гарчиг'],['subtitle','설명','Description','説明','Тайлбар']]),'번역');HanpassExport.download(new Blob([XLSX.write(wb,{type:'array',bookType:'xlsx'})]),'hanpass-translations.xlsx')};const source=await W().source(d);if(ticket!==epoch)return;if(!source){message('이 디자인은 배너 편집기 형식입니다. 다국어 생성은 업로드한 SVG 디자인을 선택하세요.',true);document.getElementById('dsExcel').disabled=true;return}const parsed=HanpassSvg.clean(source),nodes=[...parsed.svg.querySelectorAll('text')].filter(n=>!n.closest('defs,mask,clipPath'));if(!nodes.length){message('편집 가능한 텍스트가 없습니다. 글자를 윤곽선으로 바꾸지 않은 SVG를 업로드하세요.',true);document.getElementById('dsExcel').disabled=true;return}let config=d.translation?structuredClone(d.translation):null;const signatures=nodes.map(n=>n.id||[n.getAttribute('x'),n.getAttribute('y'),n.textContent].join('|'));if(config?.signatures){config.bindings=signatures.map(key=>{const i=config.signatures.indexOf(key);return i>=0?config.bindings[i]:null})}const persistTranslation=()=>{config.signatures=signatures;if(new TextEncoder().encode(JSON.stringify(config)).length>1200000)throw Error('번역표가 너무 큽니다. 필요한 문구만 남겨 다시 업로드하세요.');W().save({...d,translation:config})};const show=()=>{if(!config)return;const {table,bindings,source:src}=config;document.getElementById('dsTranslationBody').innerHTML=`<p>${E(config.fileName)} · ${table.rows.length}행</p><label class="ds-field">원문 언어<select id="dsSource">${table.columns.map(c=>`<option value="${c.code}" ${src===c.code?'selected':''}>${E(lang(c.code))}</option>`).join('')}</select></label><h2>엑셀 미리보기</h2><div class="ds-table"><table><thead><tr><th>key / 행</th>${table.columns.map(c=>`<th>${E(c.code)}</th>`).join('')}</tr></thead><tbody>${table.rows.slice(0,30).map(r=>`<tr><td>${E(r.key||r.number)}</td>${table.columns.map(c=>`<td>${E(r.values[c.code])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>미리보기는 최대 30행입니다.</p><h2>디자인 텍스트 연결</h2>${nodes.map((n,i)=>`<label class="ds-map"><span>${E(n.textContent.slice(0,100))}</span><select data-map="${i}"><option value="">연결하지 않음</option>${table.rows.map(r=>`<option value="${r.number}" ${bindings[i]===r.number?'selected':''}>${E(r.key||r.number+'행')} · ${E((r.values[src]||'').slice(0,60))}</option>`).join('')}</select></label>`).join('')}<button id="dsSaveTranslation" class="ds-secondary">번역 연결 저장</button>`;document.getElementById('dsSource').onchange=e=>{config.source=e.target.value;config.bindings=autoMap(nodes,table,config.source);show()};document.querySelectorAll('[data-map]').forEach(el=>el.onchange=()=>{config.bindings[+el.dataset.map]=+el.value||null;summary()});document.getElementById('dsSaveTranslation').onclick=()=>{try{persistTranslation();message('번역표와 문구 연결을 저장했습니다.')}catch(e){message(e.message,true)}};summary()};function summary(){const table=config.table,linked=config.bindings.filter(Boolean).length,duplicates=table.rows.filter(r=>r.key&&table.rows.filter(x=>x.key===r.key).length>1).length;document.getElementById('dsConnection').innerHTML=`<h1>${linked} / ${nodes.length}</h1><p>연결된 텍스트</p>${duplicates?`<div class="ds-warn">중복 key ${duplicates}행 · 연결 내용을 확인하세요.</div>`:''}<div class="ds-checks">${table.columns.map(c=>`<label><input type="checkbox" data-language="${c.code}" checked>${E(lang(c.code))} (${c.code})</label>`).join('')}</div><p>빈 번역은 원문으로 유지됩니다.</p>`;document.getElementById('dsGenerate').disabled=!linked}document.getElementById('dsExcelFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{book=XLSX.read(await f.arrayBuffer(),{type:'array',sheetRows:10002,cellHTML:false,cellFormula:false});bookName=f.name;const sheet=document.getElementById('dsSheet');sheet.replaceChildren(...book.SheetNames.map(n=>new Option(n,n)));document.getElementById('dsSheetWrap').hidden=false;const read=()=>{try{const matrix=XLSX.utils.sheet_to_json(book.Sheets[sheet.value],{header:1,defval:'',raw:false});if(matrix.length>=10002)throw Error('10,000행 이하로 나누어 주세요.');const table=T().parse(matrix),src=table.columns.find(c=>c.code==='KR')?.code||table.columns[0].code;config={fileName:bookName,table,source:src,bindings:autoMap(nodes,table,src)};show();message('언어 열을 인식했습니다. 문구 연결을 확인한 뒤 저장하세요.')}catch(err){message(err.message,true)}};sheet.onchange=read;read()}catch(err){message(err.message,true)}};document.getElementById('dsGenerate').onclick=async()=>{const codes=[...document.querySelectorAll('[data-language]:checked')].map(e=>e.dataset.language);if(!codes.length)return message('언어를 선택하세요.',true);busy=true;document.getElementById('dsGenerate').disabled=true;try{persistTranslation();let count=0;for(const code of codes){message(`${lang(code)} 디자인을 생성하고 있습니다…`);const result=await translated(source,config,code,document.getElementById('dsFit').checked);const ref=await HanpassDesignStorage.save(result);W().save({...d,id:crypto.randomUUID(),name:name(d)+' · '+lang(code),svgRef:ref,svgDesign:undefined,translation:undefined,parentId:d.id,language:code});count++}selected=d.id;busy=false;go('variants');message(count+'개 언어 디자인을 생성했습니다. 글꼴과 줄바꿈을 검수해 주세요.')}catch(e){message(e.message,true)}finally{busy=false;const b=document.getElementById('dsGenerate');if(b)b.disabled=false}};show()}
 function autoMap(nodes,table,source){return nodes.map(n=>{const byKey=table.rows.filter(r=>r.key&&(r.key===n.id||n.id.endsWith('-'+r.key))),found=byKey.length===1?byKey:T().matches(n.textContent,table.rows,source);return found.length===1?found[0].number:null})}
 async function translated(source,config,code,fit){const p=HanpassSvg.clean(source),svg=p.svg,holder=document.createElement('div');holder.style.cssText='position:fixed;left:-20000px;top:0;visibility:hidden';holder.append(svg);document.body.append(holder);try{await document.fonts.ready;const nodes=[...svg.querySelectorAll('text')].filter(n=>!n.closest('defs,mask,clipPath'));nodes.forEach((node,i)=>{const r=config.table.rows.find(r=>r.number===config.bindings[i]),value=r?.values[code];if(!T().norm(value))return;const width=node.getBBox().width,fs=parseFloat(getComputedStyle(node).fontSize),first=node.querySelector('tspan');for(const a of ['x','y'])if(!node.hasAttribute(a)&&first?.hasAttribute(a))node.setAttribute(a,first.getAttribute(a));const x=node.getAttribute('x')||'0';node.replaceChildren();String(value).split(/\r?\n/).forEach((line,j)=>{const t=document.createElementNS('http://www.w3.org/2000/svg','tspan');t.setAttribute('x',x);t.setAttribute('dy',j?'1.25em':'0');t.textContent=line;node.append(t)});if(fit&&width>0){const after=node.getBBox().width;if(after>width)node.setAttribute('font-size',Math.max(1,fs*width/after))}});return HanpassSvg.serialize(svg)}finally{holder.remove()}}
 function variants(){const d=project(),list=d?docs().filter(x=>x.parentId===d.id):[];shell('variants',title('언어별 디자인을 한눈에 확인하세요','저장된 언어별 결과를 검수하고 각 디자인을 따로 편집할 수 있습니다.')+selectProject()+`<div class="ds-row ds-section"><button class="ds-secondary" data-ds-nav="translations">번역 연결·다시 생성</button><button class="ds-primary" data-ds-nav="downloads">선택한 디자인 다운로드</button></div><div class="ds-grid">${list.length?list.map(d=>card(d)).join(''):'<div class="ds-empty">아직 언어별 결과가 없습니다. 번역 엑셀에서 생성해 주세요.</div>'}</div>`);bindProject('variants');previews()}
 async function exportFile(d,type,scale,transparent){await document.fonts.ready;const source=await W().source(d);if(type==='svg'){if(!source)throw Error('SVG 다운로드는 SVG 디자인만 지원합니다.');return new Blob([HanpassSvg.serialize(HanpassSvg.clean(source).svg)],{type:'image/svg+xml'})}let canvas;if(source){const p=HanpassSvg.clean(source);if(p.width*p.height*scale*scale>24000000)throw Error('해상도가 2,400만 픽셀을 초과합니다. 배율을 줄여 주세요.');canvas=document.createElement('canvas');canvas.width=Math.ceil(p.width*scale);canvas.height=Math.ceil(p.height*scale);const im=new Image();im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(HanpassSvg.serialize(p.svg));await im.decode();const c=canvas.getContext('2d');if(!transparent||type!=='png'){c.fillStyle='white';c.fillRect(0,0,canvas.width,canvas.height)}c.drawImage(im,0,0,canvas.width,canvas.height)}else{const original=await W().raster(d);if(original.width*original.height*scale*scale>24000000)throw Error('해상도가 너무 큽니다.');canvas=document.createElement('canvas');canvas.width=original.width*scale;canvas.height=original.height*scale;canvas.getContext('2d').drawImage(original,0,0,canvas.width,canvas.height)}const blob=await new Promise(r=>canvas.toBlob(r,type==='png'?'image/png':'image/jpeg',.95));if(!blob)throw Error('이미지를 내보내지 못했습니다.');return type==='pdf'?HanpassExport.pdf(new Uint8Array(await blob.arrayBuffer()),canvas.width,canvas.height):blob}
 function downloads(){const d=project(),list=d?[d,...docs().filter(x=>x.parentId===d.id)]:[];shell('downloads',title('완성한 디자인을 한 번에 다운로드','선택한 디자인을 PNG, JPG, PDF 또는 SVG로 내보냅니다.')+`<div class="ds-two"><section class="ds-panel">${selectProject()}<label class="ds-field">파일 형식<select id="dsFormat"><option value="png">PNG</option><option value="jpg">JPG</option><option value="pdf">PDF (이미지 기반)</option><option value="svg">SVG (SVG 원본만)</option></select></label><label class="ds-field">해상도<select id="dsScale"><option value="1">원본 크기 · 1배</option><option value="2">2배</option><option value="3">3배</option></select></label><label class="ds-field">파일 이름<input id="dsFilename" value="hanpass_{lang}" maxlength="80"></label><label class="ds-field"><input id="dsTransparent" type="checkbox" checked> PNG 투명 영역 유지 (원본 배경은 유지)</label><label class="ds-field"><input id="dsZip" type="checkbox" checked> 선택한 파일을 ZIP으로 묶기</label><button id="dsDownload" class="ds-primary" ${list.length?'':'disabled'}>↓ 다운로드</button><p>PDF는 이미지 기반이며, SVG의 글꼴은 설치 환경에 따라 달라질 수 있습니다.</p></section><section><h2>다운로드 미리보기</h2><div class="ds-grid">${list.map(d=>card(d,true)).join('')}</div></section></div>`);bindProject('downloads');previews();document.getElementById('dsDownload').onclick=async e=>{const chosen=[...document.querySelectorAll('[data-export-id]:checked')].map(el=>docs().find(d=>d.id===el.dataset.exportId));if(!chosen.length)return message('디자인을 선택하세요.',true);const type=document.getElementById('dsFormat').value,scale=+document.getElementById('dsScale').value,filename=(document.getElementById('dsFilename').value||'hanpass_{lang}').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_'),transparent=document.getElementById('dsTransparent').checked,asZip=document.getElementById('dsZip').checked;busy=true;e.target.disabled=true;try{const files=[];for(const [i,d]of chosen.entries()){message(`${i+1}/${chosen.length} 파일을 준비하고 있습니다…`);const blob=await exportFile(d,type,scale,transparent),n=filename.replaceAll('{lang}',d.language||'original')+'_'+(i+1)+'.'+type;files.push({name:n,bytes:new Uint8Array(await blob.arrayBuffer()),blob})}if(asZip)HanpassExport.download(HanpassExport.zip(files),'hanpass-designs.zip');else files.forEach(f=>HanpassExport.download(f.blob,f.name));message(files.length+'개 파일 다운로드를 시작했습니다.')}catch(err){message(err.message,true)}finally{busy=false;e.target.disabled=false}}}
 async function automation(){const ticket=epoch;shell('automation',title('저장한 디자인을 일정에 맞춰 업데이트','선택한 원본·언어별 디자인을 새 작업으로 복제합니다. 공개 게시 없이 계정 안에 저장됩니다.')+`<section class="ds-panel"><h2>업데이트 일정</h2><div id="dsAutomation"><p>일정 정보를 불러오는 중…</p></div></section>`);try{const res=await fetch('/api/automation');if(!res.ok)throw Error('자동 업데이트는 온라인 로그인 상태에서 사용할 수 있습니다.');const {config={},logs=[]}=await res.json();if(ticket!==epoch)return;document.getElementById('dsAutomation').innerHTML=`<div class="ds-two"><div><label class="ds-field"><input id="dsAutoEnabled" type="checkbox" ${config.enabled?'checked':''}> 매일 자동 생성</label><label class="ds-field">실행 시간 · Asia/Seoul<input id="dsAutoTime" type="time" step="3600" value="${E(config.time||'09:00')}"></label><label class="ds-field">생성 개수<select id="dsAutoCount">${[1,2,3,6,12].map(n=>`<option ${n===config.count?'selected':''}>${n}</option>`).join('')}</select></label><h2>원본 디자인 선택</h2><div class="ds-checks">${docs().filter(d=>!d.automated).map(d=>`<label><input type="checkbox" data-auto-id="${E(d.id)}" ${(config.ids||[]).includes(d.id)?'checked':''}>${E(name(d))}</label>`).join('')}</div><div class="ds-row"><button id="dsAutoSave" class="ds-primary">설정 저장</button><button id="dsAutoRun">지금 생성</button></div><p>정각에 실행됩니다. 선택한 디자인을 순서대로 복제하며, 문구·배치·색상을 임의로 생성하지 않습니다.</p></div><div><h2>실행 기록</h2>${logs.length?logs.map(l=>`<p>${E(date(l.at))} · ${l.count}개 생성</p>`).join(''):'<p>아직 실행 기록이 없습니다.</p>'}</div></div>`;const save=async run=>{if(busy)return;const config={enabled:document.getElementById('dsAutoEnabled').checked,time:document.getElementById('dsAutoTime').value,count:+document.getElementById('dsAutoCount').value,ids:[...document.querySelectorAll('[data-auto-id]:checked')].map(e=>e.dataset.autoId)};if(!config.ids.length)return message('원본 디자인을 선택하세요.',true);busy=true;try{const r=await fetch('/api/automation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({config,run})}),body=await r.json();if(!r.ok)throw Error(body.error||'설정을 저장하지 못했습니다.');if(body.projects?.length)await W().refresh();message(run?'새 디자인을 생성했습니다. 대시보드에서 확인하세요.':'일정을 저장했습니다.')}catch(e){message(e.message,true)}finally{busy=false}};document.getElementById('dsAutoSave').onclick=()=>save(false);document.getElementById('dsAutoRun').onclick=()=>save(true)}catch(e){message(e.message,true)}}
 function render(page){if(!W()||!routes.has(page))return false;epoch++;if(['mine','campaigns','templates'].includes(page))page='home';if(page==='home')dashboard();if(page==='upload')upload();if(page==='translations')translations().catch(e=>message(e.message,true));if(page==='variants')variants();if(page==='downloads')downloads();if(page==='automation')automation();if(page==='editor'){const d=project();if(d){W().open(d.id)}else{shell('editor',title('편집할 디자인을 선택하세요','먼저 디자인을 업로드하거나 배너 템플릿으로 시작하세요.')+'<button class="ds-primary" data-ds-nav="upload">디자인 업로드</button>')}}return true}
 function editorShell(host,leave){const editor=host.querySelector('.sv-editor');const wrapper=document.createElement('div');wrapper.className='ds-shell ds-editor-shell';wrapper.innerHTML='<header class="ds-header"><span class="ds-logo">hanpass<small>Creative Studio</small></span><span>다국어 디자인 편집기</span><span id="fwStatus" class="ds-sync" role="status"></span><span class="ds-account">'+E(W().email||'로컬 사용자')+'</span></header><aside class="ds-sidebar">'+nav.map(([p,i,n])=>'<button data-editor-route="'+p+'" class="'+(p==='editor'?'active':'')+'"><span>'+i+'</span>'+n+'</button>').join('')+'</aside>';wrapper.append(editor);host.replaceChildren(wrapper);wrapper.querySelectorAll('[data-editor-route]').forEach(b=>b.onclick=()=>{if(b.dataset.editorRoute!=='editor')leave(b.dataset.editorRoute)})}
 window.HanpassStudio={render,translated,autoMap,editorShell};
})();
